 34	function homeRules() {
 35	  const home = os.homedir();
 36	  const user = os.userInfo().username;
 37	  const rules = [];
 38	  if (home && home !== '/') rules.push([new RegExp(escape(home), 'g'), '~']);
 39	  // Other absolute home dirs (e.g. transcripts recorded on another machine).
 40	  rules.push([/\/(?:Users|home)\/[^/\s"'\\]+/g, '~']);
 41	  // Claude Code encodes the project dir as -Users-<name>-Projects-...
 42	  if (user) rules.push([new RegExp(`-(?:Users|home)-${escape(user)}-`, 'g'), '-~-']);
