 59	  ['access_key', /access_key=[REDACTED]\[REDACTED)[^\s"'&\\]/i],
 60	  [
 61	    'secret assignment',
 62	    /\b[A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD)[A-Z0-9_]*=(?!\[REDACTED)[^\s"'&\\]/,
 63	  ],
 64	  ['anthropic key', /sk-ant-[A-Za-z0-9_-]{10,}/],
 65	  ['home path', /\/(?:Users|home)\/[^/\s"'\\~]/],
 66	];
