 68	/** Returns a list of `{ kind, sample }` for anything that still looks sensitive. */
 69	export function findLeaks(text) {
 70	  const found = [];
 71	  for (const [kind, re] of LEAKS) {
 72	    const m = text.match(re);
 73	    if (m) found.push({ kind, sample: text.slice(Math.max(0, m.index - 20), m.index + 40) });
 74	  }
 75	  return found;
