  3	 * Archive a Claude Code session into ai/sessions/.
  4	 *
  5	 *   --hook                     SessionEnd hook mode: read hook JSON from stdin, re-launch
  6	 *                              detached (SessionEnd hooks get a very short time budget), exit 0.
  7	 *   --transcript <path>        Archive this transcript (manual use / migration).
  8	 *   [--session-id <id>]        Override the id (default: from the transcript).
  9	 *   [--out <dir>]              Output dir (default: <repo>/ai/sessions).
 10	 *
 11	 * Writes (all redacted):
 12	 *   <out>/raw/<date>-<id>.jsonl            main transcript
 13	 *   <out>/raw/<date>-<id>.<agentId>.jsonl  one per subagent
 14	 *   <out>/<date>-<id>.md                   readable rendering
 15	 *   <out>/README.md                        regenerated index
 16	 * Exits non-zero if anything sensitive survives redaction.
 17	 */
 18	import { spawn } from 'node:child_process';
 19	import { existsSync, mkdirSync, openSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
 20	import path from 'node:path';
 21	import { fileURLToPath } from 'node:url';
 22	import { parseArgs } from 'node:util';
 23	import { findLeaks, redact } from './lib/redact.mjs';
 24	import { parseJsonl, renderSession, summarize } from './lib/render.mjs';
 25	
 26	const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
 27	const SELF = fileURLToPath(import.meta.url);
 28	
 29	async function readStdin() {
 30	  let data = '';
 31	  for await (const chunk of process.stdin) data += chunk;
 32	  return data;
 33	}
 34	
 35	async function hookMode(outDir) {
 36	  const input = JSON.parse((await readStdin()) || '{}');
 37	  if (!input.transcript_path || !existsSync(input.transcript_path)) return;
 38	  mkdirSync(outDir, { recursive: true });
 39	  const log = openSync(path.join(outDir, '.archive.log'), 'a');
 40	  const args = [SELF, '--transcript', input.transcript_path, '--out', outDir];
 41	  if (input.session_id) args.push('--session-id', input.session_id);
 42	  // Detach so archiving finishes after Claude Code exits; failures land in .archive.log.
 43	  spawn(process.execPath, args, { detached: true, stdio: ['ignore', log, log] }).unref();
 44	}
 45	
 46	function loadSubagents(transcriptPath, sessionId) {
 47	  const dir = path.join(path.dirname(transcriptPath), sessionId, 'subagents');
 48	  if (!existsSync(dir)) return [];
 49	  return readdirSync(dir)
 50	    .filter((f) => /^agent-.+\.jsonl$/.test(f))
 51	    .sort()
 52	    .map((f) => {
 53	      const agentId = f.slice('agent-'.length, -'.jsonl'.length);
 54	      const metaPath = path.join(dir, `agent-${agentId}.meta.json`);
 55	      const raw = readFileSync(path.join(dir, f), 'utf8');
 56	      return {
 57	        agentId,
 58	        raw,
 59	        entries: parseJsonl(raw),
 60	        meta: existsSync(metaPath) ? JSON.parse(readFileSync(metaPath, 'utf8')) : null,
 61	      };
 62	    });
 63	}
 64	
 65	const redactJsonl = (raw) => raw.split('\n').map(redact).join('\n');
 66	
 67	export function archive({ transcript, sessionId, outDir }) {
 68	  const raw = readFileSync(transcript, 'utf8');
 69	  const entries = parseJsonl(raw);
 70	  const meta = summarize(entries);
 71	  const id = sessionId ?? meta.sessionId ?? path.basename(transcript, '.jsonl');
 72	  if (!meta.started) throw new Error(`No timestamps in ${transcript}; cannot date the session.`);
 73	  const base = `${meta.started.slice(0, 10)}-${id}`;
 74	  const subagents = loadSubagents(transcript, id);
 75	
 76	  const rawDir = path.join(outDir, 'raw');
 77	  mkdirSync(rawDir, { recursive: true });
 78	  const written = [];
 79	  const write = (file, content) => {
 80	    writeFileSync(file, content);
 81	    written.push(file);
 82	  };
 83	  write(path.join(rawDir, `${base}.jsonl`), redactJsonl(raw));
 84	  for (const a of subagents)
 85	    write(path.join(rawDir, `${base}.${a.agentId}.jsonl`), redactJsonl(a.raw));
 86	  write(path.join(outDir, `${base}.md`), redact(renderSession({ entries, subagents })));
 87	  write(path.join(outDir, 'README.md'), renderIndex(outDir));
 88	
 89	  const leaks = written.flatMap((file) =>
 90	    findLeaks(readFileSync(file, 'utf8')).map((l) => ({ file: path.relative(REPO, file), ...l })),
 91	  );
 92	  return { base, written, leaks };
 93	}
