100	    .filter(({ m }) => m)
101	    .map(({ f, m }) => {
102	      const md = readFileSync(path.join(outDir, f), 'utf8');
103	      const field = (label) =>
104	        md.match(new RegExp(`\\*\\*${label}:\\*\\* ([^·\\n]+)`))?.[1].trim() ?? '';
105	      return {
106	        f,
107	        date: m[1],
108	        id: m[2],
109	        title: md.match(/^# (.+)$/m)?.[1] ?? '',
110	        started: field('Started'),
111	        prompts: field('Prompts'),
112	        tools: field('Tool calls'),
113	        subagents: field('Subagents'),
114	      };
115	    })
116	    .sort((a, b) => a.started.localeCompare(b.started));
117	
118	  return [
119	    '# AI sessions',
120	    '',
121	    'Every Claude Code session on this repo, archived automatically by the `SessionEnd` hook',
122	    '(`scripts/archive-session.mjs`). Each row links a readable rendering; the redacted raw',
123	    'transcripts (main + subagents) are in [`raw/`](raw/). The narrative of what happened and',
124	    'why lives in [`AI_WORKFLOW.md`](../../AI_WORKFLOW.md) (written by `/workflow-notes`).',
125	    '',
126	    '| Started (UTC) | Title | Prompts | Tool calls | Subagents | Session |',
127	    '|---|---|---|---|---|---|',
128	    ...rows.map(
129	      (r) =>
130	        `| ${r.started.replace('T', ' ').slice(0, 16)} | [${r.title.replace(/\|/g, '\\|')}](${r.f}) | ${r.prompts} | ${r.tools} | ${r.subagents} | \`${r.id.slice(0, 8)}\` |`,
131	    ),
132	    '',
133	  ].join('\n');
134	}
